import React from "react";
import classes from "./Header.module.css";
import { NavLink, Outlet } from "react-router-dom";
import Loginmodal from "../loginmodal/Loginmodal";
import ModalStore from "../../store/ModalStore";
import { observer } from "mobx-react-lite";
import UserStore from "../../store/UserStore";
const Header = observer(() => {
  const linkStyle = [classes.navigation];
  const setActive = ({ isActive }) =>
    isActive ? linkStyle.push(classes.active) : " ";
  return (
    <>
      <header className={classes.header}>
        <NavLink className={classes.logo} to="/main">
          Коннект
        </NavLink>
        <nav>
          <NavLink className={setActive} to="/vote">
            голосование
          </NavLink>
          <NavLink className={setActive} to="/">
            афиша
          </NavLink>
          <NavLink className={setActive} to="/dada">
            обсуждения
          </NavLink>
        </nav>
        {UserStore.isAuthenticated ? (
          <button className={classes.header__btn}>
            <p className={classes.header__btn_text}>
              {UserStore.first_name} {UserStore.last_name}
            </p>{" "}
          </button>
        ) : (
          <button
            className={classes.header__btn}
            onClick={() => ModalStore.setVisible(true)}>
            <p className={classes.header__btn_text}>войти</p>{" "}
          </button>
        )}
      </header>
      <Loginmodal visible={ModalStore.visible} />
      <Outlet />
    </>
  );
});
export { Header };
